"""Independent literals/algebra, not references generated by the tested helper."""
from pathlib import Path
import math
import sys
import unittest
import numpy as np

ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'src'))
from afsd_backend.pysph.hht_curved_identity import kinetic_identity
from afsd_backend.pysph import hht_path


def fixture():
    return dict(mass=np.array([2.]),v0=np.array([[.3,-.2,.1]]),
        v1=np.array([[.31,-.071,.14]]),acc0=np.array([[1.,.7,.2]]),
        acc1=np.array([[-.5,101/60,8/15]]),force0=np.array([[3.,1.,0.]]),
        force1=np.array([[-2.,4.,1.]]),dt=.1,
        delta_impulse_Ns=np.array([[.03,-.02,.01]]),delta_material_work_J=np.array([.017]))


class CurvedIdentity(unittest.TestCase):
    def test_hand_computed_nonzero_history_and_work_correction(self):
        r=kinetic_identity(**fixture())
        np.testing.assert_allclose(r['physical_impulse_Ns'],[[.08,.23,.06]],atol=1e-13,rtol=0)
        np.testing.assert_allclose(r['algorithmic_filter_impulse_Ns'],[[-.06,.028,.02]],atol=1e-13,rtol=0)
        self.assertAlmostEqual(float(r['delta_kinetic_J'][0]),-.019259,delta=1e-13)
        # Independently integrated force/velocity cubic: .1*(.7-1.846275/2
        # +.39845/3-.016175/4), not a call to hht_path.linear_work.
        wlin=.1*(.7-1.846275/2+.39845/3-.016175/4)
        self.assertAlmostEqual(float(r['baseline_linear_force_work_J'][0]),wlin,delta=1e-13)
        self.assertAlmostEqual(float(r['physical_force_work_J'][0]),wlin+.017,delta=1e-13)
        self.assertAlmostEqual(float(r['curved_algorithmic_filter_work_J'][0]),-.00394,delta=1e-13)
        self.assertNotIn('physical_linear_force_work_J',r)
        np.testing.assert_allclose(r['root_residual_impulse_Ns'],0,atol=1e-13,rtol=0)
        np.testing.assert_allclose(r['momentum_identity_residual_Ns'],0,atol=1e-13,rtol=0)
        np.testing.assert_allclose(r['kinetic_identity_residual_J'],0,atol=1e-13,rtol=0)
        self.assertTrue(r['algorithmic_work_is_not_heat'])
        self.assertTrue(r['algorithmic_work_sign_not_assumed'])

    def test_actual_returned_velocity_and_root_defects_remain_visible(self):
        p=fixture();da=np.array([[.002,-.003,.004]])
        p['acc1']=p['acc1']+da
        # Direct Newmark formula, independent of tested endpoint/path routines.
        predicted=p['v0']+.1*(.4*p['acc0']+.6*p['acc1'])
        dv=np.array([[.003,-.004,.002]]);p['v1']=predicted+dv
        r=kinetic_identity(**p)
        np.testing.assert_allclose(r['root_residual_impulse_Ns'],.1*.6*2*da,atol=1e-13,rtol=0)
        np.testing.assert_allclose(r['kinematic_velocity_residual_m_s'],dv,atol=1e-13,rtol=0)
        np.testing.assert_allclose(r['momentum_identity_residual_Ns'],2*dv,atol=1e-13,rtol=0)
        expected=np.sum(2*dv*(p['v0']+p['v1'])/2,axis=-1)
        np.testing.assert_allclose(r['kinetic_identity_residual_J'],expected,atol=1e-13,rtol=0)

    def test_zero_correction_exact_old_decomposition_reduction(self):
        p=fixture();p['delta_impulse_Ns'][:]=0;p['delta_material_work_J'][:]=0
        r=kinetic_identity(**p)
        old=hht_path.kinetic_identity(**{k:v for k,v in p.items() if not k.startswith('delta_')})
        for key in ('physical_impulse_Ns','algorithmic_filter_impulse_Ns',
                    'root_residual_impulse_Ns','algorithmic_filter_work_J',
                    'root_residual_work_J','momentum_identity_residual_Ns',
                    'kinetic_identity_residual_J','delta_kinetic_J'):
            np.testing.assert_array_equal(r[key],old[key])
        np.testing.assert_array_equal(r['physical_force_work_J'],old['physical_linear_force_work_J'])
        np.testing.assert_array_equal(r['curved_algorithmic_filter_work_J'],0)

    def test_a_one_retains_nonzero_acceleration_history(self):
        p=fixture();p['weight']=1.
        p['acc1']=(p['force1']+p['delta_impulse_Ns']/(.5*p['dt']))/p['mass'][:,None]
        p['v1']=p['v0']+.5*p['dt']*(p['acc0']+p['acc1'])
        r=kinetic_identity(**p)
        # q=0 but old r0=(-1,.4,.4) is not zero; undamped-control labels
        # do not authorize erasing its filter impulse/history.
        np.testing.assert_allclose(r['algorithmic_filter_impulse_Ns'],[[-.05,.02,.02]],atol=1e-13,rtol=0)
        np.testing.assert_allclose(r['momentum_identity_residual_Ns'],0,atol=1e-13,rtol=0)
        np.testing.assert_allclose(r['kinetic_identity_residual_J'],0,atol=1e-13,rtol=0)

    def test_galilean_work_and_impulse_transformations(self):
        p=fixture();r=kinetic_identity(**p);boost=np.array([[.8,-1.1,.6]])
        q=dict(p,v0=p['v0']+boost,v1=p['v1']+boost,
            delta_material_work_J=p['delta_material_work_J']+np.sum(p['delta_impulse_Ns']*boost,axis=-1))
        s=kinetic_identity(**q)
        for key in ('physical_impulse_Ns','algorithmic_filter_impulse_Ns','root_residual_impulse_Ns'):
            np.testing.assert_allclose(s[key],r[key],atol=1e-12,rtol=0)
        np.testing.assert_allclose(s['curved_algorithmic_filter_work_J'],r['curved_algorithmic_filter_work_J'],atol=1e-12,rtol=0)
        np.testing.assert_allclose(s['physical_force_work_J']-r['physical_force_work_J'],
            np.sum(boost*r['physical_impulse_Ns'],axis=-1),atol=1e-12,rtol=0)
        np.testing.assert_allclose(s['algorithmic_filter_work_J']-r['algorithmic_filter_work_J'],
            np.sum(boost*r['algorithmic_filter_impulse_Ns'],axis=-1),atol=1e-12,rtol=0)
        np.testing.assert_allclose(s['delta_kinetic_J']-r['delta_kinetic_J'],
            np.sum(boost*p['mass'][:,None]*(p['v1']-p['v0']),axis=-1),atol=1e-12,rtol=0)

    def test_analytic_curved_coulomb_force_integrals(self):
        # Prescribed contact-integration path u=(1,s,0), not a force-driven
        # material solution. Unbalanced forcing is correctly exposed as R.
        root2=math.sqrt(2);asinh1=math.log(1+root2)
        actualJ=np.array([[-asinh1,-(root2-1),0.]])
        rawQ=.5*(root2+asinh1)
        f0=np.array([[-1.,0,0]]);f1=np.array([[-1/root2,-1/root2,0]])
        chordJ=(f0+f1)/2;chordW=-(.5+5/(6*root2))
        r=kinetic_identity(np.ones(1),np.array([[1.,0,0]]),np.array([[1.,1,0]]),
            np.array([[0.,1,0]]),np.array([[0.,1,0]]),f0,f1,1.,actualJ-chordJ,np.array([-rawQ-chordW]))
        np.testing.assert_allclose(r['physical_impulse_Ns'],actualJ,atol=1e-12,rtol=0)
        self.assertAlmostEqual(float(r['physical_force_work_J'][0]),-rawQ,delta=1e-12)
        self.assertAlmostEqual(float(r['curved_algorithmic_filter_work_J'][0]),
            .5-.5*asinh1-1/(12*root2),delta=1e-12)
        self.assertGreater(float(np.linalg.norm(r['root_residual_impulse_Ns'])),1.)
        np.testing.assert_allclose(r['kinetic_identity_residual_J'],0,atol=1e-12,rtol=0)

    def test_invalid_correction_and_input_arrays_rejected(self):
        for key,value in (('delta_impulse_Ns',np.array([[np.nan,0,0]])),
                          ('delta_impulse_Ns',np.zeros(3)),
                          ('delta_material_work_J',np.array([np.inf])),
                          ('delta_material_work_J',0.),('dt',0.),
                          ('mass',np.array([-1.]))):
            p=fixture();p[key]=value
            with self.subTest(key=key,value=value):
                with self.assertRaises(ValueError):kinetic_identity(**p)


if __name__=='__main__':unittest.main(verbosity=2)
